package client

import (
	"crypto/rand"
	"fmt"
	"strings"
)

// getClientID gets client ID for logging use
func (c *Client) getClientID() string {
	if c.actualID != "" {
		return c.actualID
	}
	return c.config.ClientID
}

// generateClientID generates a unique client ID
// For SaaS mode: when client_id is pre-generated by platform (format: tunnelId-suffix),
// use it directly without adding additional suffix.
// For CLI mode: generate unique ID with replica index and short random suffix.
func generateClientID(clientID string, replicaIdx int) string {
	// If client_id already has a suffix (e.g., "tunnelId-abc123" from platform),
	// use it directly for replicaIdx 0. The platform handles uniqueness in SaaS mode.
	// Only add suffix for additional replicas or when ID doesn't have suffix.
	if replicaIdx == 0 && strings.Contains(clientID, "-") {
		// Client ID appears to be pre-generated (SaaS mode), use as-is
		return clientID
	}

	// CLI mode or additional replicas: generate unique ID with replica index and short random suffix.
	// The suffix must be random: replicas often start within the same second.
	suffix := strings.ToLower(rand.Text()[:6])
	generatedID := fmt.Sprintf("%s-r%d-%s", clientID, replicaIdx, suffix)
	return generatedID
}
